'use client';
import { Check, ChevronsUpDown } from 'lucide-react';
import { type ComponentProps, type ReactNode, useMemo, useState } from 'react';
import Link from 'fumadocs-core/link';
import { usePathname } from 'fumadocs-core/framework';
import { cn } from 'local:utils/cn.ts';
import { Popover, PopoverContent, PopoverTrigger } from 'local:components/ui/popover.tsx';
import { AnimatePresence, motion } from 'motion/react';
import { isLayoutTabActive, type LayoutTab } from 'local:<dir>/shared/index.tsx';

export interface TabDropdownProps extends ComponentProps<'button'> {
  placeholder?: ReactNode;
  tabs: LayoutTab[];
}

export function TabDropdown({ tabs, placeholder, className, ...props }: TabDropdownProps) {
  const [open, setOpen] = useState(false);
  const pathname = usePathname();
  const selectedIdx = useMemo(() => {
    return tabs.findLastIndex((item) => isLayoutTabActive(item, pathname));
  }, [tabs, pathname]);
  const selected = selectedIdx !== -1 ? tabs[selectedIdx] : undefined;

  const onClick = () => {
    setOpen(false);
  };

  const item = selected ? (
    <>
      <div className="size-4.5 shrink-0 empty:hidden">{selected.icon}</div>
      <p className="font-medium">{selected.title}</p>
    </>
  ) : (
    placeholder
  );

  return (
    <Popover open={open} onOpenChange={setOpen}>
      {item && (
        <PopoverTrigger
          className={cn(
            'flex items-center gap-2 rounded-xl overflow-hidden p-1.5 border shadow-sm text-sm text-start transition-colors hover:bg-fd-accent hover:text-fd-accent-foreground data-[state=open]:bg-fd-accent data-[state=open]:text-fd-accent-foreground',
            className,
          )}
          {...props}
        >
          <AnimatePresence mode="popLayout">
            <motion.span
              key={selectedIdx}
              className="flex w-full min-w-0 overflow-hidden items-center text-nowrap gap-1.5"
              initial={{
                opacity: 0,
                y: '100%',
              }}
              animate={{
                opacity: 1,
                y: 0,
              }}
              exit={{
                opacity: 0,
                y: '-100%',
              }}
            >
              {item}
            </motion.span>
          </AnimatePresence>

          <ChevronsUpDown className="shrink-0 ms-auto size-4 text-fd-muted-foreground" />
        </PopoverTrigger>
      )}
      <PopoverContent
        align="start"
        className="flex flex-col gap-1 max-w-svw p-1 fd-scroll-container"
      >
        {tabs.map((item, i) => {
          const isActive = i === selectedIdx;
          if (!isActive && item.unlisted) return;

          return (
            <Link
              key={item.url}
              href={item.url}
              onClick={onClick}
              {...item.props}
              className={cn(
                'flex items-center gap-1.5 rounded-lg p-1.5 hover:bg-fd-accent hover:text-fd-accent-foreground',
                item.props?.className,
              )}
            >
              <div className="shrink-0 mb-auto size-4.5 empty:hidden">{item.icon}</div>
              <div>
                <p className="text-sm font-medium leading-none">{item.title}</p>
                <p className="text-[0.8125rem] text-fd-muted-foreground mt-1 empty:hidden">
                  {item.description}
                </p>
              </div>

              <Check
                className={cn(
                  'shrink-0 ms-auto size-3.5 text-fd-primary',
                  !isActive && 'invisible',
                )}
              />
            </Link>
          );
        })}
      </PopoverContent>
    </Popover>
  );
}
